"use client";

import Link from "next/link";
import { z } from "zod";
import { formatMoney } from "@/lib/finance/format";
import { minorDigits } from "@/lib/finance/fx";
import { ReactECharts, useThemeColors } from "./chart";

// Model-written charts can only use these fields, so no code or styling reaches the page.
const amount = z.string().regex(/^-?(?:0|[1-9]\d{0,79})$/);
const text = z.string().trim().min(1).max(60);
const unit = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("money"), currency: z.string().regex(/^[A-Z]{3}$/) }).strict(),
  z.object({ kind: z.literal("count") }).strict(),
]);
const href = z.string().max(500).regex(/^\/money\/transactions\?[\w=&%.-]*$/).optional();
const header = { title: z.string().trim().min(1).max(80), unit };
const cartesian = z.object({
  ...header,
  type: z.enum(["bar", "line", "area"]),
  horizontal: z.boolean().optional(),
  stacked: z.boolean().optional(),
  labels: z.array(text).min(2).max(24),
  series: z.array(z.object({ name: text, values: z.array(amount).min(1).max(24) }).strict()).min(1).max(4),
}).strict().refine(chart => chart.series.every(series => series.values.length === chart.labels.length), "Each series needs one value per label");
const circular = z.object({
  ...header,
  type: z.enum(["pie", "donut", "treemap", "bubble"]),
  items: z.array(z.object({ label: text, value: amount, href }).strict()).min(2).max(20),
}).strict().refine(chart => chart.items.every(item => !item.value.startsWith("-")), "Values must not be negative");
const chartSchema = z.union([cartesian, circular]);
type ChartSpec = z.infer<typeof chartSchema>;
type CartesianSpec = z.infer<typeof cartesian>;
type CircularSpec = z.infer<typeof circular>;
type ChartUnit = ChartSpec["unit"];

// Same family as the app's charts. Each series or item keeps its colour in the chart and in its table row.
const PALETTE = ["#5266eb", "#9cb4e8", "#f0806c", "#7a8699", "#4fb3bf", "#d9a93a", "#9b87f5", "#a6cf3f", "#d16ba5", "#5c9e31", "#b5651d", "#2a6fdb"];
const GAP = 3;
const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const percent = new Intl.NumberFormat("en-US", { style: "percent", maximumFractionDigits: 1 });

function formatAmount(value: string, chartUnit: ChartUnit) {
  return chartUnit.kind === "money" ? formatMoney(value, chartUnit.currency) : BigInt(value).toLocaleString("en-US");
}
// Plotting uses major units for scale only; every number a reader sees comes from formatAmount.
function plotValue(value: string, chartUnit: ChartUnit) {
  return chartUnit.kind === "money" ? Number(value) / 10 ** minorDigits(chartUnit.currency) : Number(value);
}
const escapeHtml = (value: string) => value.replace(/[&<>"']/g, character => `&#${character.charCodeAt(0)};`);

/** Circles that never overlap; each one goes to the nearest free spot on a spiral out from the centre. */
function packCircles(radii: number[]) {
  const placed: { x: number; y: number; r: number }[] = [];
  for (const r of radii) {
    const clear = (x: number, y: number) => placed.every(other => Math.hypot(x - other.x, y - other.y) >= r + other.r + GAP);
    let angle = 0, x = 0, y = 0;
    while (placed.length && !clear(x, y)) {
      angle += 0.05;
      const distance = angle * 3;
      x = distance * Math.cos(angle);
      y = distance * Math.sin(angle);
    }
    placed.push({ x, y, r });
  }
  return placed;
}

function ChartTable({ chart }: { chart: ChartSpec }) {
  if ("labels" in chart) return <div className="mt-3 overflow-x-auto"><table className="w-full text-sm tabular-nums">
    <thead className="text-xs text-muted-foreground"><tr><th className="py-1 text-left font-normal" />{chart.series.map((series, col) => <th key={col} className="py-1 text-right font-normal"><span className="mr-1.5 inline-block size-2 rounded-full align-middle" style={{ background: PALETTE[col % PALETTE.length] }} aria-hidden="true" />{series.name}</th>)}</tr></thead>
    <tbody>{chart.labels.map((label, row) => <tr key={row} className="border-t border-border">
      <th scope="row" className="py-1.5 pr-3 text-left font-normal [overflow-wrap:anywhere]">{label}</th>
      {chart.series.map((series, col) => <td key={col} className="py-1.5 text-right">{formatAmount(series.values[row], chart.unit)}</td>)}
    </tr>)}</tbody>
  </table></div>;
  const total = chart.items.reduce((sum, item) => sum + BigInt(item.value), 0n);
  return <div className="mt-3 overflow-x-auto"><table className="w-full text-sm tabular-nums">
    <thead className="text-xs text-muted-foreground"><tr><th className="py-1 text-left font-normal">Item</th><th className="py-1 text-right font-normal">Amount</th><th className="py-1 text-right font-normal">Share</th></tr></thead>
    <tbody>{chart.items.map((item, index) => <tr key={index} className="border-t border-border">
      <th scope="row" className="py-1.5 pr-3 text-left font-normal [overflow-wrap:anywhere]"><span className="mr-1.5 inline-block size-2 rounded-full align-middle" style={{ background: PALETTE[index % PALETTE.length] }} aria-hidden="true" />{item.href ? <Link href={item.href} className="hover:underline" title="Open matching transactions">{item.label}</Link> : item.label}</th>
      <td className="py-1.5 text-right">{formatAmount(item.value, chart.unit)}</td>
      <td className="py-1.5 text-right text-muted-foreground">{total ? percent.format(Number(item.value) / Number(total)) : "0%"}</td>
    </tr>)}</tbody>
    <tfoot><tr className="border-t border-border font-medium"><th scope="row" className="py-1.5 pr-3 text-left font-medium">Total</th><td className="py-1.5 text-right">{formatAmount(total.toString(), chart.unit)}</td><td className="py-1.5 text-right">100%</td></tr></tfoot>
  </table></div>;
}

function CartesianChart({ chart }: { chart: CartesianSpec }) {
  const colors = useThemeColors();
  const { type, unit, labels, series } = chart;
  const horizontal = type === "bar" && chart.horizontal === true;
  const axisLabel = { color: colors.muted };
  const categories = { type: "category", data: labels, inverse: horizontal, axisLine: { lineStyle: { color: colors.border } }, axisTick: { show: false }, axisLabel: { ...axisLabel, hideOverlap: true } };
  const values = { type: "value", name: unit.kind === "money" ? unit.currency : undefined, nameTextStyle: axisLabel, axisLabel: { ...axisLabel, formatter: (value: number) => compact.format(value) }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } };
  return <ReactECharts notMerge style={{ height: 260 }} option={{
    color: PALETTE,
    grid: { left: 8, right: 12, top: series.length > 1 ? 32 : 12, bottom: 8, containLabel: true },
    legend: series.length > 1 ? { top: 0, textStyle: axisLabel } : undefined,
    tooltip: { trigger: "axis", formatter: (items: { axisValueLabel: string; seriesIndex: number; dataIndex: number; seriesName: string; color: string }[]) => [escapeHtml(items[0]?.axisValueLabel ?? ""), ...items.map(item => `<span style="color:${item.color}">●</span> ${escapeHtml(item.seriesName)}: ${formatAmount(series[item.seriesIndex].values[item.dataIndex], unit)}`)].join("<br/>") },
    xAxis: horizontal ? values : categories,
    yAxis: horizontal ? categories : values,
    series: series.map(item => ({
      name: item.name,
      type: type === "bar" ? "bar" : "line",
      data: item.values.map(value => plotValue(value, unit)),
      stack: chart.stacked ? "total" : undefined,
      barMaxWidth: 36,
      smooth: type !== "bar",
      symbol: "none",
      areaStyle: type === "area" ? { opacity: 0.18 } : undefined,
    })),
  }} />;
}

function CircularChart({ chart }: { chart: CircularSpec }) {
  const colors = useThemeColors();
  const { type, unit, items } = chart;
  const values = items.map(item => Number(item.value));
  const total = items.reduce((sum, item) => sum + BigInt(item.value), 0n);
  if (type === "bubble") {
    // Circle area is proportional to amount, so the biggest item sets the scale.
    const largest = Math.max(...values) || 1;
    const order = items.map((_, index) => index).sort((a, b) => values[b] - values[a]);
    const circles = packCircles(order.map(index => Math.max(3, 100 * Math.sqrt(values[index] / largest))));
    const minX = Math.min(...circles.map(c => c.x - c.r)) - 4, minY = Math.min(...circles.map(c => c.y - c.r)) - 4;
    const maxX = Math.max(...circles.map(c => c.x + c.r)) + 4, maxY = Math.max(...circles.map(c => c.y + c.r)) + 4;
    return <svg role="img" aria-label={chart.title} viewBox={`${minX} ${minY} ${maxX - minX} ${maxY - minY}`} className="mx-auto h-64 w-full">
      {order.map((index, slot) => <circle key={index} cx={circles[slot].x} cy={circles[slot].y} r={circles[slot].r} fill={PALETTE[index % PALETTE.length]} fillOpacity={0.9}>
        <title>{`${items[index].label}: ${formatAmount(items[index].value, unit)}`}</title>
      </circle>)}
    </svg>;
  }
  const describe = (index: number) => `${escapeHtml(items[index].label)}: ${formatAmount(items[index].value, unit)} (${percent.format(values[index] / Number(total || 1n))})`;
  const data = items.map((item, index) => ({ name: item.label, value: plotValue(item.value, unit), itemStyle: { color: PALETTE[index % PALETTE.length] } }));
  return <ReactECharts notMerge style={{ height: 260 }} option={{
    tooltip: { formatter: (params: { dataIndex: number }) => describe(params.dataIndex) },
    series: type === "treemap"
      ? [{ type: "treemap", data, roam: false, breadcrumb: { show: false }, upperLabel: { show: false }, label: { color: colors.card, overflow: "truncate" }, itemStyle: { borderColor: colors.card, borderWidth: 2, gapWidth: 2 } }]
      : [{ type: "pie", data, radius: type === "donut" ? ["55%", "80%"] : "75%", label: { show: false }, labelLine: { show: false }, itemStyle: { borderColor: colors.card, borderWidth: 2 } }],
  }} />;
}

/** Renders a model-written ```moneo-chart block: a bar, line, area, pie, donut, treemap or bubble chart plus its exact values. */
export function ChatChart({ source }: { source: string }) {
  let chart: ChartSpec | undefined;
  try { chart = chartSchema.parse(JSON.parse(source)); } catch { chart = undefined; }
  if (!chart) return <p className="my-2 text-sm text-muted-foreground">The chart could not be drawn from this data.</p>;
  return <figure className="ai-chart my-4 min-w-0 max-w-full rounded-xl border border-border bg-card p-4" aria-label={chart.title}>
    <figcaption className="mb-3 text-sm font-medium">{chart.title}</figcaption>
    {"labels" in chart ? <CartesianChart chart={chart} /> : <CircularChart chart={chart} />}
    <ChartTable chart={chart} />
  </figure>;
}
"use client";

import { useMemo, useSyncExternalStore } from "react";
import dynamic from "next/dynamic";

// Loaded on the client only, so echarts never ships in the server render or blocks first paint.
// A trimmed echarts (see echarts-lean) serves app and chat charts alike.
export const ReactECharts = dynamic(() => import("./echarts-lean"), { ssr: false });
// Pages that import this module eagerly (Plan) start the echarts download before their chart renders.
if (typeof window !== "undefined") void import("./echarts-lean");

function subscribeTheme(onChange: () => void) {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  return () => observer.disconnect();
}

/** Resolves a color token to a concrete color; tokens are light-dark() pairs, which ECharts cannot parse. */
function token(name: string, fallback: string) {
  if (typeof document === "undefined") return fallback;
  const probe = document.createElement("span");
  probe.style.color = `var(${name})`;
  document.body.appendChild(probe);
  const color = getComputedStyle(probe).color;
  probe.remove();
  return color || fallback;
}

// Chart colors follow the app's CSS tokens, including the dark theme.
export function useThemeColors() {
  const theme = useSyncExternalStore(subscribeTheme, () => document.documentElement.dataset.theme ?? "light", () => "light");
  return useMemo(() => {
    const fallback = theme === "dark" ? { brand: "#cbf26b", muted: "#a3a39e", border: "#24262a", card: "#16171a", input: "#3987e5", output: "#d95926", out: "#5b5d62" } : { brand: "#4a6400", muted: "#5c5d58", border: "#e2e0d8", card: "#ffffff", input: "#2a78d6", output: "#eb6834", out: "#a9aaa3" };
    return { brand: token("--color-brand", fallback.brand), muted: token("--color-muted-foreground", fallback.muted), border: token("--color-border", fallback.border), card: token("--color-card", fallback.card), input: token("--color-chart-input", fallback.input), output: token("--color-chart-output", fallback.output), out: token("--color-chart-out", fallback.out) };
  }, [theme]);
}

/** Money in vs money out per month; `flow` shows one side only. Bars are major units for pixel scale only. */
export function CashFlowChart({ labels, income, spending, flow, selected, picked, height = 240, formatValue, onSelect }: {
  labels: string[]; income: number[]; spending: number[]; flow?: "in" | "out"; selected?: number; picked?: "in" | "out"; height?: number;
  formatValue?: (value: number) => string; onSelect?: (index: number, flow: "in" | "out") => void;
}) {
  const colors = useThemeColors();
  const bar = { type: "bar", barMaxWidth: 28, barGap: "20%", itemStyle: { borderRadius: [4, 4, 0, 0] } };
  // With a month picked, the other months fade so the breakdown below clearly belongs to it.
  const points = (values: number[]) => values.map((value, index) => selected === undefined || index === selected ? value : { value, itemStyle: { opacity: 0.35 } });
  // The dashed line marks the picked month on the side (in or out) that was clicked.
  const marker = (side: "in" | "out") => selected !== undefined && picked === side
    ? { markLine: { symbol: "none", silent: true, label: { show: false }, lineStyle: { type: "dashed", color: colors.muted, width: 1.5 }, data: [{ xAxis: labels[selected] }] } } : {};
  const series = [
    ...(flow !== "out" ? [{ ...bar, name: "In", data: points(income), itemStyle: { ...bar.itemStyle, color: colors.brand }, ...marker("in") }] : []),
    ...(flow !== "in" ? [{ ...bar, name: "Out", data: points(spending), itemStyle: { ...bar.itemStyle, color: colors.out }, ...marker("out") }] : []),
  ];
  // The box keeps its height while echarts loads, so the card around it does not collapse and grow back.
  return <div role="img" aria-label="Money in and out for each of the last six months" style={{ height }}>
    <ReactECharts
      notMerge
      option={{
        grid: { left: 0, right: 0, top: 8, bottom: 0, containLabel: true },
        tooltip: { trigger: "axis", ...(formatValue ? { valueFormatter: formatValue } : {}) },
        xAxis: { type: "category", data: labels, axisLine: { lineStyle: { color: colors.border } }, axisTick: { show: false }, axisLabel: { color: colors.muted, fontFamily: "monospace" } },
        yAxis: { type: "value", axisLabel: { show: false }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } },
        series,
      }}
      style={{ height, cursor: onSelect ? "pointer" : undefined }}
      onEvents={onSelect ? { click: (event: { dataIndex: number; seriesName: string }) => onSelect(event.dataIndex, event.seriesName === "In" ? "in" : "out") } : undefined}
    />
  </div>;
}

type ForecastChartDay ={ date: string; expected: number; conservative: number; optimistic: number };
type ForecastChartObligation = { date: string; name: string; amount: string };

// Approximate chart coordinates (major units as numbers); exact amounts are rendered by the caller.
export function ForecastChart({ days, obligations, currency, label, compare }: {
  days: ForecastChartDay[]; obligations: ForecastChartObligation[]; currency: string; label: string;
  /** Optional second expected line, e.g. the real plan while a what-if scenario is shown. */
  compare?: { name: string; values: number[] };
}) {
  const brand = token("--color-brand", "#cbf26b"), muted = token("--color-muted-foreground", "#a3a39e"), border = token("--color-border", "#24262a");
  const expectedOn = new Map(days.map(day => [day.date, day.expected]));
  return <div role="img" aria-label={label}>
    <ReactECharts style={{ height: 260 }} option={{
      grid: { left: 8, right: 16, top: 24, bottom: 8, containLabel: true },
      tooltip: { trigger: "axis", renderMode: "richText", formatter: (items: { dataIndex: number }[]) => {
        const day = days[items[0]?.dataIndex];
        if (!day) return "";
        const due = obligations.filter(item => item.date === day.date).map(item => `\n${item.name}: ${item.amount}`).join("");
        return `${day.date}\nExpected ${currency} ${day.expected.toFixed(2)}\nConservative ${currency} ${day.conservative.toFixed(2)}${compare ? `\n${compare.name} ${currency} ${compare.values[items[0].dataIndex]?.toFixed(2)}` : ""}${due}`;
      } },
      xAxis: { type: "category", boundaryGap: false, data: days.map(day => day.date), axisLabel: { color: muted }, axisLine: { lineStyle: { color: border } } },
      yAxis: { type: "value", scale: true, axisLabel: { color: muted }, splitLine: { lineStyle: { color: border, type: "dashed" } } },
      series: [
        { name: "Conservative", type: "line", stack: "band", symbol: "none", lineStyle: { opacity: 0 }, data: days.map(day => day.conservative) },
        { name: "Range", type: "line", stack: "band", symbol: "none", lineStyle: { opacity: 0 }, areaStyle: { color: brand, opacity: 0.12 },
          data: days.map(day => day.optimistic - day.conservative) },
        { name: "Expected", type: "line", symbol: "none", lineStyle: { color: brand, width: 2.5 }, data: days.map(day => day.expected) },
        ...(compare ? [{ name: compare.name, type: "line", symbol: "none", lineStyle: { color: muted, width: 1.5, type: "dashed" }, data: compare.values }] : []),
        { name: "Obligations", type: "scatter", symbolSize: 9, itemStyle: { color: muted }, tooltip: { show: false },
          data: [...new Set(obligations.map(item => item.date))].filter(date => expectedOn.has(date)).map(date => [date, expectedOn.get(date)]) },
      ],
    }} />
  </div>;
}
"use client";

import ReactEChartsCore from "echarts-for-react/lib/core";
import type { EChartsReactProps } from "echarts-for-react/lib/types";
import * as echarts from "echarts/core";
import { BarChart, LineChart, PieChart, ScatterChart, TreemapChart } from "echarts/charts";
import { GridComponent, LegendComponent, MarkLineComponent, TooltipComponent } from "echarts/components";
import { CanvasRenderer } from "echarts/renderers";

// Only the chart types the app draws, app-owned and model-written alike.
echarts.use([BarChart, LineChart, ScatterChart, PieChart, TreemapChart, GridComponent, LegendComponent, MarkLineComponent, TooltipComponent, CanvasRenderer]);

export default function LeanECharts(props: Omit<EChartsReactProps, "echarts">) {
  return <ReactEChartsCore echarts={echarts} {...props} />;
}
"use client";

import { useState } from "react";
import { minorDigits } from "@/lib/finance/fx";

type Series = { name: string; values: (number | null)[]; color?: string };
export type CardChartProps = { type: "line" | "area" | "bar" | "hbar" | "donut" | "sparkline"; labels: string[]; series: Series[]; stacked?: boolean; axis?: boolean; currency?: string; minor?: boolean; height?: number; className?: string; style?: React.CSSProperties };

// The app's own chart colours, in order, for series that don't pick one.
const PALETTE = ["var(--color-brand)", "var(--color-ai)", "var(--color-chart-out)", "var(--color-warning)", "var(--color-chart-input)", "var(--color-success)", "var(--color-danger)", "var(--color-muted-foreground)"];
const W = 600;

/** A chart value as shown: minor-unit values (cents) are divided down to the currency's major unit first. */
export function format(value: number | null | undefined, currency?: string, minor?: boolean) {
  if (value === null || value === undefined) return "–";
  if (currency && minor) value = value / 10 ** minorDigits(currency);
  return currency ? new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: Math.abs(value) >= 1000 ? 0 : 2 }).format(value)
    : new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(value);
}

/** Charts drawn as SVG by the app from the card's numbers; the card never passes code or HTML to a chart. */
export function CardChart({ type, labels, series, stacked, axis, currency, minor, height, className, style }: CardChartProps) {
  const shown = (value: number | null | undefined) => format(value, currency, minor);
  const [active, setActive] = useState<number | null>(null);
  const colors = series.map((item, index) => item.color ?? PALETTE[index % PALETTE.length]);
  const count = Math.max(labels.length, ...series.map(item => item.values.length));
  const tooltip = active !== null && <div role="status" className="pointer-events-none absolute top-0 z-10 rounded-lg border border-border bg-card px-2.5 py-1.5 text-xs shadow-lg"
    style={{ left: `clamp(0px, calc(${((active + 0.5) / count) * 100}% - 4rem), calc(100% - 8rem))` }}>
    {labels[active] && <p className="text-muted-foreground">{labels[active]}</p>}
    {series.map((item, index) => <p key={item.name} className="flex items-center gap-1.5 whitespace-nowrap font-mono"><span className="size-2 rounded-full" style={{ background: colors[index] }} />{series.length > 1 && `${item.name} `}{shown(item.values[active])}</p>)}
  </div>;

  if (type === "donut") {
    const values = series[0].values.map(value => Math.max(0, value ?? 0));
    const total = values.reduce((sum, value) => sum + value, 0) || 1;
    // Each slice starts where the ones before it end.
    const starts = values.map((_, index) => values.slice(0, index).reduce((sum, value) => sum + (value / total) * 100, 0));
    const size = height ?? 140;
    return <div className={`relative flex items-center gap-4 ${className ?? ""}`} style={style} onPointerLeave={() => setActive(null)}>
      <svg viewBox="0 0 42 42" width={size} height={size} role="img" aria-label={series[0].name} className="shrink-0 -rotate-90">
        <circle cx="21" cy="21" r="15.915" fill="none" stroke="var(--color-muted)" strokeWidth="6" />
        {values.map((value, index) => {
          const share = (value / total) * 100, dash = `${share} ${100 - share}`, start = starts[index];
          return <circle key={index} cx="21" cy="21" r="15.915" fill="none" stroke={PALETTE[index % PALETTE.length]} strokeWidth={active === index ? 7.5 : 6}
            strokeDasharray={dash} strokeDashoffset={-start} onPointerEnter={() => setActive(index)} className="transition-[stroke-width]" />;
        })}
      </svg>
      <ul className="min-w-0 flex-1 space-y-1 text-xs">{values.map((value, index) => <li key={index} onPointerEnter={() => setActive(index)} className={`flex items-center gap-2 ${active === null || active === index ? "" : "opacity-50"}`}>
        <span className="size-2 shrink-0 rounded-full" style={{ background: PALETTE[index % PALETTE.length] }} /><span className="min-w-0 flex-1 truncate">{labels[index]}</span><span className="font-mono">{shown(value)}</span></li>)}</ul>
    </div>;
  }

  if (type === "hbar") {
    const values = series[0].values;
    const max = Math.max(...values.map(value => Math.abs(value ?? 0)), 1);
    return <ul className={`space-y-2 text-sm ${className ?? ""}`} style={style}>{values.map((value, index) => <li key={index}>
      <div className="flex justify-between gap-3"><span className="truncate">{labels[index]}</span><span className="shrink-0 font-mono text-xs">{shown(value)}</span></div>
      <div className="mt-1 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full" style={{ width: `${(Math.abs(value ?? 0) / max) * 100}%`, background: colors[0] }} /></div>
    </li>)}</ul>;
  }

  const h = height ?? (type === "sparkline" ? 40 : 140);
  const totals = Array.from({ length: count }, (_, index) => series.reduce((sum, item) => sum + Math.max(0, item.values[index] ?? 0), 0));
  const all = stacked && type === "bar" ? totals : series.flatMap(item => item.values.filter((value): value is number => value !== null));
  const min = type === "bar" ? Math.min(0, ...all) : Math.min(...all), max = Math.max(...all, min + 1);
  const y = (value: number) => h - 2 - ((value - min) / (max - min)) * (h - 4);
  const x = (index: number) => count === 1 ? W / 2 : (index / (count - 1)) * W;
  const band = W / Math.max(count, 1);
